   detail::range_mapper<buffer_context<Char>> mapper;
   auto out = ctx.out();
   out = write_range_opening(out);
   int i = 0;
   auto it = detail::range_begin(range);
   auto end = detail::range_end(range);
   for (; it != end; ++it) {
     if (i > 0) out = write_range_separator(out);
     ;
     ctx.advance_to(out);
     out = underlying_.format(mapper.map(*it), ctx);
     ++i;
   }
   out = write_range_closing(out);
   return out;
