#include <cassert>
#include <ranges>
#include <string>
#include <string_view>
#include <vector>
#include <fmt/ranges.h>

struct range_to_sv {
  std::string s;
  auto begin() const { return s.begin(); }
  auto end() const { return s.end(); }
  operator std::string_view() const { return s; }
};

struct string_like {
  const char* begin();
  const char* end();
  operator fmt::string_view() const { return "foo"; }
  operator std::string_view() const { return "foo"; }
};

int main() {
  std::string s = "abc";
  assert(fmt::format("{}", range_to_sv{s}) == "['a', 'b', 'c']");
  assert(fmt::format("{}", string_like()) == "foo");
  assert(fmt::format("{}", std::vector<char>{'a', 'b'}) == "['a', 'b']");
}

